import traceback
class End(Exception): pass

for mode in ('cause', 'context', 'none', 'suppressed'):
    try:
        try:
            if mode == 'cause':
                try: raise KeyError('root')
                except KeyError as e: raise ValueError('app') from e
            if mode == 'context':
                try: raise KeyError('root')
                except KeyError: raise ValueError('app')
            if mode == 'suppressed':
                try: raise KeyError('root')
                except KeyError: raise ValueError('app') from None
            raise ValueError('app')
        except ValueError as app:
            saved = app
        try:
            raise End('stream')
        except End:
            raise saved
    except Exception as exc:
        print(mode, 'cause=', repr(exc.__cause__), 'context=', repr(exc.__context__), 'suppress=', exc.__suppress_context__)
        traceback.print_exception(exc)
