import traceback
import anyio
from starlette.middleware.base import BaseHTTPMiddleware
from starlette.responses import Response

async def dispatch(request, call_next):
    return await call_next(request)

async def receive():
    return {'type': 'http.request', 'body': b'', 'more_body': False}

async def send(message):
    pass

scope = {'type': 'http', 'method': 'GET', 'path': '/', 'headers': []}

async def run(mode):
    async def app(scope, receive, send):
        if mode == 'context':
            try:
                raise KeyError('root')
            except KeyError:
                raise ValueError('app')
        if mode == 'cause':
            try:
                raise KeyError('root')
            except KeyError as exc:
                raise ValueError('app') from exc
        raise ValueError('app')
    try:
        await BaseHTTPMiddleware(app, dispatch)(scope, receive, send)
    except Exception as exc:
        print(mode, type(exc.__cause__).__name__ if exc.__cause__ else None, type(exc.__context__).__name__ if exc.__context__ else None, exc.__suppress_context__)
        print(''.join(traceback.format_exception(exc)))

async def main():
    for mode in ('context', 'cause', 'none'):
        await run(mode)
anyio.run(main)
